#!/usr/bin/env python3
import sys, os, re, unicodedata
from dataclasses import dataclass
from typing import tuple, list, Dict, Optional

VERSION = "grex 1.4.6"
HELP = """grex 1.4.6
© 2019-today Peter M. Stahl <pemistahl@gmail.com>
Licensed under the Apache License, Version 2.0
Downloadable from https://crates.io/crates/grex
Source code at https://github.com/pemistahl/grex

grex generates regular expressions from user-provided test cases.

Usage: grex [OPTIONS] {INPUT...|--file <FILE>}

Input:
  [INPUT]...         One or more test cases separated by blank space
  -f, --file <FILE>  Reads test cases on separate lines from a file

Digit Options:
  -d, --digits      Converts any Unicode decimal digit to \\d
  -D, --non-digits  Converts any character which is not a Unicode decimal digit to \\D

Whitespace Options:
  -s, --spaces      Converts any Unicode whitespace character to \\s
  -S, --non-spaces  Converts any character which is not a Unicode whitespace character to \\S

Word Options:
  -w, --words      Converts any Unicode word character to \\w
  -W, --non-words  Converts any character which is not a Unicode word character to \\W

Escaping Options:
  -e, --escape           Replaces all non-ASCII characters with unicode escape sequences
      --with-surrogates  Converts astral code points to surrogate pairs if --escape is set

Repetition Options:
  -r, --repetitions                    Detects repeated non-overlapping substrings and converts them
                                       to {min,max} quantifier notation
      --min-repetitions <QUANTITY>     Specifies the minimum quantity of substring repetitions to be
                                       converted if --repetitions is set [default: 1]
      --min-substring-length <LENGTH>  Specifies the minimum length a repeated substring must have
                                       in order to be converted if --repetitions is set [default: 1]

Anchor Options:
      --no-start-anchor  Removes the caret anchor `^` from the resulting regular expression
      --no-end-anchor    Removes the dollar sign anchor `$` from the resulting regular expression
      --no-anchors       Removes the caret and dollar sign anchors from the resulting regular
                         expression

Display Options:
  -x, --verbose   Produces a nicer-looking regular expression in verbose mode
  -c, --colorize  Provides syntax highlighting for the resulting regular expression

Miscellaneous Options:
  -i, --ignore-case     Performs case-insensitive matching, letters match both upper and lower case
  -g, --capture-groups  Replaces non-capturing groups with capturing ones
  -h, --help            Prints help information
  -v, --version         Prints version information"""

@dataclass(frozen=True)
class Tok:
    pat: str
    raw: str
    kind: str = "lit"       # lit, cls, quant
    base: tuple = ()
    count: int = 1
    lit: Optional[str] = None
    priority: int = 100
    unit_len: int = 1

@dataclass
class R:
    pat: str
    min_len: int
    max_len: int
    key: str
    simple: bool = False
    seq: tuple = ()

class Opt:
    def __init__(self):
        self.digits=False; self.nondigits=False; self.spaces=False; self.nonspaces=False
        self.words=False; self.nonwords=False; self.escape=False; self.surrogates=False
        self.repetitions=False; self.min_repetitions=1; self.min_sub_len=1
        self.start_anchor=True; self.end_anchor=True; self.verbose=False; self.color=False
        self.ignore_case=False; self.capture=False; self.file=None

SHORTS=set("dDsSwWerxcighv")
LONG_NO_VALUE={
    "digits":"digits","non-digits":"nondigits","spaces":"spaces","non-spaces":"nonspaces",
    "words":"words","non-words":"nonwords","escape":"escape","with-surrogates":"surrogates",
    "repetitions":"repetitions","no-start-anchor":"no_start","no-end-anchor":"no_end",
    "no-anchors":"no_anchors","verbose":"verbose","colorize":"color","ignore-case":"ignore_case",
    "capture-groups":"capture","help":"help","version":"version"
}
LONG_VALUE={"file":"file","min-repetitions":"min_repetitions","min-substring-length":"min_sub_len"}


def usage_error(msg):
    sys.stderr.write(f"error: {msg}\n\nUsage: grex [OPTIONS] {{INPUT...|--file <FILE>}}\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def value_error(opt, val, what):
    sys.stderr.write(f"error: invalid value '{val}' for '--{opt} <{what}>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def zero_error(opt, val, what):
    sys.stderr.write(f"error: invalid value '{val}' for '--{opt} <{what}>': Value must not be zero\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def set_flag(opt:Opt, name):
    if name=="digits": opt.digits=True
    elif name=="nondigits": opt.nondigits=True
    elif name=="spaces": opt.spaces=True
    elif name=="nonspaces": opt.nonspaces=True
    elif name=="words": opt.words=True
    elif name=="nonwords": opt.nonwords=True
    elif name=="escape": opt.escape=True
    elif name=="surrogates": opt.surrogates=True
    elif name=="repetitions": opt.repetitions=True
    elif name=="no_start": opt.start_anchor=False
    elif name=="no_end": opt.end_anchor=False
    elif name=="no_anchors": opt.start_anchor=False; opt.end_anchor=False
    elif name=="verbose": opt.verbose=True
    elif name=="color": opt.color=True
    elif name=="ignore_case": opt.ignore_case=True
    elif name=="capture": opt.capture=True

def parse_uint(name, val, metavar):
    if not re.fullmatch(r"[0-9]+", val or ""):
        value_error(name, val, metavar)
    n=int(val)
    if n==0:
        zero_error(name, val, metavar)
    return n

def parse_args(argv):
    opt=Opt(); inputs=[]; i=0; parsing=True
    while i<len(argv):
        a=argv[i]
        if parsing and a.startswith("--") and len(a)>2:
            body=a[2:]; val=None
            if "=" in body:
                body,val=body.split("=",1)
            if body in LONG_NO_VALUE:
                if val is not None:
                    # clap would reject, but this is rare; treat as positional fallback for permissive inputs
                    parsing=False; inputs.append(a); i+=1; continue
                nm=LONG_NO_VALUE[body]
                if nm=="help": print(HELP); sys.exit(0)
                if nm=="version": print(VERSION); sys.exit(0)
                set_flag(opt,nm); i+=1; continue
            if body in LONG_VALUE:
                nm=LONG_VALUE[body]
                if val is None:
                    if i+1>=len(argv):
                        usage_error(f"a value is required for '--{body} <{'FILE' if body=='file' else ('QUANTITY' if body=='min-repetitions' else 'LENGTH')}>' but none was supplied")
                    val=argv[i+1]; i+=1
                if nm=="file": opt.file=val
                elif nm=="min_repetitions": opt.min_repetitions=parse_uint(body,val,"QUANTITY")
                elif nm=="min_sub_len": opt.min_sub_len=parse_uint(body,val,"LENGTH")
                i+=1; continue
            parsing=False; inputs.append(a); i+=1; continue
        elif parsing and a.startswith("-") and len(a)>1:
            body=a[1:]
            if all(ch in SHORTS for ch in body):
                # grouped flags; -f is not in SHORTS because it requires a value
                for ch in body:
                    if ch=='h': print(HELP); sys.exit(0)
                    if ch=='v': print(VERSION); sys.exit(0)
                    set_flag(opt, {'d':'digits','D':'nondigits','s':'spaces','S':'nonspaces','w':'words','W':'nonwords','e':'escape','r':'repetitions','x':'verbose','c':'color','i':'ignore_case','g':'capture'}[ch])
                i+=1; continue
            elif body=='f':
                if i+1>=len(argv):
                    sys.stderr.write("error: a value is required for '--file <FILE>' but none was supplied\n\nFor more information, try '--help'.\n")
                    sys.exit(2)
                opt.file=argv[i+1]; i+=2; continue
            else:
                parsing=False; inputs.append(a); i+=1; continue
        else:
            parsing=False; inputs.append(a); i+=1
    if opt.surrogates and not opt.escape:
        sys.stderr.write("error: the following required arguments were not provided:\n  --escape\n\nUsage: grex [OPTIONS] {INPUT...|--file <FILE>}\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    if opt.file is not None and inputs:
        sys.stderr.write("error: the argument '--file <FILE>' cannot be used with '[INPUT]...'\n\nUsage: grex [OPTIONS] {INPUT...|--file <FILE>}\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    if opt.file is None and not inputs:
        sys.stderr.write("error: the following required arguments were not provided:\n  --file <FILE>\n  <INPUT>...\n\nUsage: grex [OPTIONS] {INPUT...|--file <FILE>}\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    return opt, inputs


def read_cases(opt, inputs):
    if opt.file is not None:
        try:
            data=open(opt.file,'rb').read().decode('utf-8')
        except FileNotFoundError:
            sys.stderr.write("error: the specified file could not be found\n"); sys.exit(1)
        except Exception:
            sys.stderr.write("error: the specified file could not be read\n"); sys.exit(1)
        lines=data.splitlines()
        non=[x for x in lines if x!=""]
        return non if non else [""]
    if len(inputs)==1 and inputs[0]=='-':
        data=sys.stdin.read()
        lines=data.splitlines()
        non=[x for x in lines if x!=""]
        if not lines:
            sys.stderr.write("\nthread 'main' panicked at /workspace/src/builder.rs:48:13:\nNo test cases have been provided for regular expression generation\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            sys.exit(101)
        return non if non else [""]
    return inputs

# ---- tokenization / escaping ----

def graphemes(s):
    out=[]; cur=""
    for ch in s:
        cat=unicodedata.category(ch)
        if cur and (unicodedata.combining(ch) or cat in ("Mn","Mc","Me") or ch=='\ufe0f'):
            cur+=ch
        else:
            if cur: out.append(cur)
            cur=ch
    if cur: out.append(cur)
    return out

META=set('\\.+*?^${}()|[]-')

def esc_char(ch):
    mp={'\t':'\\t','\n':'\\n','\r':'\\r','\v':'\\v','\f':'\\f','\a':'\\a','\b':'\\b'}
    if ch in mp: return mp[ch]
    if ch in META: return '\\'+ch
    return ch

def lit_pat(g, opt):
    parts=[]
    for ch in g:
        cp=ord(ch)
        if opt.escape and cp>127:
            if opt.surrogates and cp>0xFFFF:
                u=cp-0x10000; hi=0xD800+(u>>10); lo=0xDC00+(u&0x3FF)
                parts.append(f"\\u{{{hi:x}}}\\u{{{lo:x}}}")
            else:
                parts.append(f"\\u{{{cp:x}}}")
        else:
            parts.append(esc_char(ch))
    return ''.join(parts)

def is_decimal(g): return len(g)==1 and g.isdecimal()
def is_space(g): return len(g)==1 and g.isspace()
def is_word(g):
    if len(g)==1:
        return (g=='_' or g.isalnum() or unicodedata.category(g).startswith('M'))
    # a base letter followed by combining marks is treated as one word grapheme
    return all((ch=='_' or ch.isalnum() or unicodedata.category(ch).startswith('M')) for ch in g)

def make_class(name):
    pri={'\\d':0,'\\s':1,'\\w':2,'\\D':200,'\\S':201,'\\W':202}[name]
    return Tok(name,name,'cls',lit=None,priority=pri)

def make_lit(g,opt):
    p=lit_pat(g,opt)
    # put literals after positive shorthand classes and before negative shorthand classes
    first=ord(g[0]) if g else 0
    return Tok(p,g,'lit',lit=g,priority=50,unit_len=1)

def tokenize_case(s,opt):
    if opt.ignore_case:
        s=s.lower()
    toks=[]
    for g in graphemes(s):
        t=None
        if opt.digits and is_decimal(g): t=make_class('\\d')
        elif opt.spaces and is_space(g): t=make_class('\\s')
        elif opt.words and is_word(g): t=make_class('\\w')
        elif opt.nondigits and not is_decimal(g): t=make_class('\\D')
        elif opt.nonspaces and not is_space(g): t=make_class('\\S')
        elif opt.nonwords and not is_word(g): t=make_class('\\W')
        else: t=make_lit(g,opt)
        toks.append(t)
    return tuple(toks)

# ---- repetition conversion ----

def primitive(seq):
    n=len(seq)
    for l in range(1,n//2+1):
        if n%l==0 and seq[:l]*(n//l)==seq:
            return False
    return True

def quant_pattern(base, count):
    inner=''.join(t.pat for t in base)
    if len(base)==1 and is_simple_atom_text(inner):
        pat=inner+f"{{{count}}}"
    else:
        pat=f"(?:{inner})"+f"{{{count}}}"
    raw=''.join(t.raw for t in base)
    return Tok(pat, raw, 'quant', base=tuple(base), count=count, lit=None, priority=50, unit_len=1)

def compress_once(seq,opt):
    n=len(seq); best=None
    min_total=opt.min_repetitions+1
    for i in range(n):
        for L in range(opt.min_sub_len, (n-i)//min_total + 1):
            base=seq[i:i+L]
            if not primitive(base):
                continue
            k=1
            while i+(k+1)*L<=n and seq[i+k*L:i+(k+1)*L]==base:
                k+=1
            if k>=min_total:
                cover=k*L; reaches=(i+cover==n)
                score=(cover, 1 if reaches else 0, -L, -i)
                if best is None or score>best[0]:
                    best=(score,i,L,k)
    if best is None: return tuple(seq), False
    _,i,L,k=best
    before,_=compress_repetitions(seq[:i],opt)
    base,_=compress_repetitions(seq[i:i+L],opt)
    after,_=compress_repetitions(seq[i+k*L:],opt)
    return tuple(before)+(quant_pattern(tuple(base),k),)+tuple(after), True

def compress_repetitions(seq,opt):
    cur=tuple(seq); changed_any=False
    while True:
        cur2,changed=compress_once(cur,opt)
        if not changed: break
        cur=cur2; changed_any=True
    return cur, changed_any

# ---- regex generation ----

def is_simple_atom_text(p):
    if not p: return False
    if p.startswith('[') and p.endswith(']'): return True
    if len(p)==1: return True
    if re.fullmatch(r"\\[dDsSwWtnrvfab.\\+*?^${}()|\[\]\-]", p): return True
    if re.fullmatch(r"\\u\{[0-9a-f]+\}", p): return True
    return False

def charclassable(t):
    return t.kind=='lit' and t.lit is not None and len(t.lit)==1 and t.lit!='\\'

def esc_class_char(ch, in_range_endpoint=False):
    if ch=='\\': return '\\\\'
    if ch=='-': return '\\-'
    if ch=='[': return '\\['
    if ch==']': return '\\]'
    if ch=='^': return '\\^'
    if ch=='\t': return '\\t'
    if ch=='\n': return '\\n'
    if ch=='\r': return '\\r'
    if ch=='\v': return '\\v'
    if ch=='\f': return '\\f'
    return ch

def make_char_class(tokens):
    chars=sorted({t.lit for t in tokens}, key=lambda c: ord(c))
    parts=[]; i=0
    while i<len(chars):
        j=i
        while j+1<len(chars) and ord(chars[j+1])==ord(chars[j])+1:
            j+=1
        run_len=j-i+1
        if run_len>=3:
            parts.append(esc_class_char(chars[i])+'-'+esc_class_char(chars[j]))
        else:
            for k in range(i,j+1): parts.append(esc_class_char(chars[k]))
        i=j+1
    return '['+''.join(parts)+']'

def tok_key(t):
    if t.kind=='cls': return (t.priority, t.raw)
    if t.kind=='lit': return (t.priority, t.raw)
    return (60, ''.join(x.raw for x in t.base), t.count)

def seq_key(seq):
    return ''.join(t.raw for t in seq)

def seq_unit_len(seq):
    return sum(t.unit_len for t in seq)

def concat(rs):
    pat=''.join(r.pat for r in rs)
    return R(pat, sum(r.min_len for r in rs), sum(r.max_len for r in rs), ''.join(r.key for r in rs), simple=(len(rs)==1 and rs[0].simple))

def regex_token(t):
    return R(t.pat, t.unit_len, t.unit_len, t.raw, simple=is_simple_atom_text(t.pat), seq=(t,))

def longest_common_prefix(seqs):
    if not seqs or any(len(s)==0 for s in seqs): return 0
    m=min(len(s) for s in seqs); i=0
    while i<m and all(s[i]==seqs[0][i] for s in seqs): i+=1
    return i

def longest_common_suffix(seqs):
    if not seqs or any(len(s)==0 for s in seqs): return 0
    m=min(len(s) for s in seqs); i=0
    while i<m and all(s[-1-i]==seqs[0][-1-i] for s in seqs): i+=1
    return i

def optify(r):
    if r.pat=='': return r
    if r.simple:
        return R(r.pat+'?',0,r.max_len,r.key,False)
    return R(f"(?:{r.pat})?",0,r.max_len,r.key,False)

def quant_variant(seq):
    # Returns (base_tuple, count, is_multibase_count1_ok) if whole seq is base repeated or one quant.
    if len(seq)==1 and seq[0].kind=='quant':
        return (seq[0].base, seq[0].count)
    # count 1 variant: either one token or a short literal base; used for grouped repeated substrings
    return (tuple(seq), 1)

def combine_quant_variants(seqs):
    if len(seqs)<2: return None
    variants=[]
    for s in seqs:
        if len(s)==0: return None
        variants.append(quant_variant(s))
    bases={v[0] for v in variants}
    if len(bases)!=1: return None
    base=next(iter(bases)); counts=sorted({v[1] for v in variants})
    # Only meaningful if at least one true repetition or a single-character base range.
    if len(base)!=1 and all(c==1 for c in counts): return None
    pieces=[]; start=prev=counts[0]
    ranges=[]
    for c in counts[1:]:
        if c==prev+1: prev=c
        else: ranges.append((start,prev)); start=prev=c
    ranges.append((start,prev))
    def piece(a,b):
        inner=''.join(t.pat for t in base)
        raw=''.join(t.raw for t in base)
        if len(base)==1:
            atom=inner
            if a==b==1: return regex_sequence((base[0],))
            if len(base)==1 and is_simple_atom_text(atom):
                q=f"{{{a}}}" if a==b else f"{{{a},{b}}}"
                return R(atom+q,1,1,raw,False)
        # multi-token base: leave count 1 as the plain base, combine repetitions >=2
        if a==b==1:
            return regex_sequence(tuple(base))
        q=f"{{{a}}}" if a==b else f"{{{a},{b}}}"
        return R(f"(?:{inner})"+q,1,1,raw,False)
    # For multi-token bases, do not fold count 1 into {1,n}; split it out.
    if len(base)>1 and ranges and ranges[0][0]==1 and ranges[0][1]>1:
        ranges=[(1,1),(2,ranges[0][1])]+ranges[1:]
    rs=[piece(a,b) for a,b in ranges]
    return combine_alternatives(rs)

def regex_sequence(seq):
    return concat([regex_token(t) for t in seq])

def combine_label_group(labels):
    labels=sorted(labels,key=tok_key)
    if len(labels)>1 and all(charclassable(t) for t in labels):
        return R(make_char_class(labels),1,1,''.join(t.raw for t in labels),True)
    rs=[regex_token(t) for t in labels]
    return combine_alternatives(rs)

def combine_alternatives(rs):
    if not rs: return R('',0,0,'',True)
    if len(rs)==1: return rs[0]
    # character class if all alternatives are individual classable literal tokens
    toks=[]
    ok=True
    for r in rs:
        if len(r.seq)==1 and charclassable(r.seq[0]): toks.append(r.seq[0])
        else: ok=False; break
    if ok and len(toks)>1:
        return R(make_char_class(toks),1,1,''.join(sorted([t.raw for t in toks])),True)
    def sk(r):
        # positive shorthands first, literals, negative shorthands when all unit length;
        # otherwise longest represented branch first, then lexicographic.
        if r.max_len==1 and r.min_len==1 and len(r.seq)==1:
            return (0, tok_key(r.seq[0]))
        return (1, -r.max_len, r.key, r.pat)
    rs=sorted(rs,key=sk)
    return R('(?:'+'|'.join(r.pat for r in rs)+')', min(r.min_len for r in rs), max(r.max_len for r in rs), min(r.key for r in rs), False)

def gen(seqs):
    # canonicalize
    seqs=sorted(set(tuple(s) for s in seqs), key=lambda s:(-seq_unit_len(s), seq_key(s)))
    if not seqs: return R('',0,0,'',True)
    if len(seqs)==1:
        return regex_sequence(seqs[0])
    if all(len(s)==0 for s in seqs): return R('',0,0,'',True)

    # Empty alternative: optionalize a suitable generated expression. For disjoint alternatives,
    # attach the empty alternative to the shortest branch, matching grex's usual style.
    empties=[s for s in seqs if len(s)==0]
    if empties:
        non=[s for s in seqs if len(s)>0]
        if not non: return R('',0,0,'',True)
        # If nonempty branches share a prefix or suffix, generate them together and make optional.
        if longest_common_prefix(non)>0 or longest_common_suffix(non)>0 or len(non)==1 or combine_quant_variants(non) is not None:
            return optify(gen(non))
        # Otherwise optionalize the shortest branch and alternate with the rest.
        non_sorted=sorted(non,key=lambda s:(seq_unit_len(s), seq_key(s)))
        short=optify(gen([non_sorted[0]]))
        rest=[gen([s]) for s in non_sorted[1:]]+[short]
        return combine_alternatives(rest)

    q=combine_quant_variants(seqs)
    if q is not None: return q

    lp=longest_common_prefix(seqs)
    if lp>0:
        pre=regex_sequence(seqs[0][:lp])
        rest=gen([s[lp:] for s in seqs])
        return concat([pre,rest])
    ls=longest_common_suffix(seqs)
    if ls>0:
        core=gen([s[:-ls] for s in seqs])
        suf=regex_sequence(seqs[0][-ls:])
        return concat([core,suf])

    # Trie-like grouping by first token; siblings with identical suffix regex are merged.
    groups: Dict[Tok,list] = {}
    for s in seqs:
        groups.setdefault(s[0],[]).append(s[1:])
    suffix_groups: Dict[str, tuple] = {}
    for t,rests in groups.items():
        rr=gen(rests)
        suffix_groups.setdefault(rr.pat, (rr,[]))[1].append(t)
    branches=[]
    for rr,labels in suffix_groups.values():
        lab=combine_label_group(labels)
        branches.append(concat([lab,rr]))
    return combine_alternatives(branches)

# ---- display ----

def apply_captures(s,opt):
    return s.replace('(?:','(') if opt.capture else s

def escape_verbose_spaces(s):
    # In verbose regex mode, literal spaces must be escaped. Avoid touching spaces in char classes.
    out=[]; in_class=False; esc=False
    for ch in s:
        if esc:
            out.append(ch); esc=False; continue
        if ch=='\\':
            out.append(ch); esc=True; continue
        if ch=='[': in_class=True; out.append(ch); continue
        if ch==']': in_class=False; out.append(ch); continue
        if ch==' ' and not in_class: out.append('\\ ')
        else: out.append(ch)
    return ''.join(out)

def split_top_alts(s):
    parts=[]; cur=[]; depth=0; cls=False; esc=False
    for ch in s:
        if esc: cur.append(ch); esc=False; continue
        if ch=='\\': cur.append(ch); esc=True; continue
        if cls:
            cur.append(ch)
            if ch==']': cls=False
            continue
        if ch=='[': cls=True; cur.append(ch); continue
