def apply_captures(s,opt):
    return s.replace('(?:','(') if opt.capture else s

def escape_verbose_spaces(s):
    # In verbose regex mode, literal spaces must be escaped. Avoid touching spaces in char classes.
    out=[]; in_class=False; esc=False
    for ch in s:
        if esc:
            out.append(ch); esc=False; continue
        if ch=='\\':
            out.append(ch); esc=True; continue
        if ch=='[': in_class=True; out.append(ch); continue
        if ch==']': in_class=False; out.append(ch); continue
        if ch==' ' and not in_class: out.append('\\ ')
        else: out.append(ch)
    return ''.join(out)

def split_top_alts(s):
    parts=[]; cur=[]; depth=0; cls=False; esc=False
    for ch in s:
        if esc: cur.append(ch); esc=False; continue
        if ch=='\\': cur.append(ch); esc=True; continue
        if cls:
            cur.append(ch)
            if ch==']': cls=False
            continue
        if ch=='[': cls=True; cur.append(ch); continue
        if ch=='(' and s.startswith('(?:', len(''.join(cur))):
            pass
        if ch=='(' : depth+=1
        elif ch==')': depth-=1
        if ch=='|' and depth==0:
            parts.append(''.join(cur)); cur=[]
        else:
            cur.append(ch)
    parts.append(''.join(cur))
    return parts

def pretty_body(s, indent=2):
    s=escape_verbose_spaces(s)
    lines=[]
    def rec(x, ind):
        # format a full non-capturing/capturing group alternation if the whole string is one
        if (x.startswith('(?:') or x.startswith('(')):
            prefix='(?:' if x.startswith('(?:') else '('
        # A small hand-written formatter for the constructs produced here.
        i=0; buf=''
        def flush():
            nonlocal buf
            if buf:
                lines.append(' '*ind+buf); buf=''
        while i<len(x):
            if x.startswith('(?:',i) or x[i]=='(':
                flush()
                cap = x[i]=='(' and not x.startswith('(?:',i)
                start='(' if cap else '(?:'
                j=i+len(start); depth=1; cls=False; esc=False
                while j<len(x):
                    ch=x[j]
                    if esc: esc=False
                    elif ch=='\\': esc=True
                    elif cls:
                        if ch==']': cls=False
                    elif ch=='[': cls=True
                    elif ch=='(' : depth+=1
                    elif ch==')':
                        depth-=1
                        if depth==0: break
                    j+=1
                inner=x[i+len(start):j]
                q=''
                k=j+1
                if k<len(x) and x[k] in '?*+': q=x[k]; k+=1
                elif k<len(x) and x[k]=='{':
                    m=x.find('}',k); q=x[k:m+1]; k=m+1
                lines.append(' '*ind+start)
                alts=split_top_alts(inner)
                for ai,a in enumerate(alts):
                    rec(a,ind+2)
                    if ai!=len(alts)-1: lines.append(' '*(ind+2)+'|')
                lines.append(' '*ind+')'+q)
                i=k
            else:
                buf+=x[i]; i+=1
        flush()
    rec(s,indent)
    return lines

def verbose_format(compact,opt):
    pref='(?ix)' if opt.ignore_case else '(?x)'
    s=compact
    if opt.ignore_case and s.startswith('(?i)'): s=s[4:]
    start=False; end=False
    if s.startswith('^'): start=True; s=s[1:]
    if s.endswith('$'): end=True; s=s[:-1]
    lines=[pref]
    if start: lines.append('^')
    lines.extend(pretty_body(s,2))
    if end: lines.append('$')
    return '\n'.join(lines)

COL_RESET='\033[0m'; COL_ANCH='\033[1;33m'; COL_BR='\033[1;36m'; COL_FLAG='\033[40;93m'

def colorize(s):
    out=[]; i=0
    while i<len(s):
        if s.startswith('(?i)',i) or s.startswith('(?x)',i) or s.startswith('(?ix)',i):
            end=s.find(')',i)+1; out.append(COL_FLAG+s[i:end]+COL_RESET); i=end; continue
        ch=s[i]
        if ch in '^$': out.append(COL_ANCH+ch+COL_RESET)
        elif ch in '[]-': out.append(COL_BR+ch+COL_RESET)
        else: out.append(ch)
        i+=1
    return ''.join(out)

def build_regex(cases,opt):
    seqs=[]
    for c in cases:
        seq=tokenize_case(c,opt)
        if opt.repetitions:
            seq,_=compress_repetitions(seq,opt)
        seqs.append(seq)
    body=gen(seqs).pat
    if opt.start_anchor: body='^'+body
    if opt.end_anchor: body=body+'$'
    if opt.ignore_case and not opt.verbose: body='(?i)'+body
    body=apply_captures(body,opt)
    if opt.verbose:
        body=verbose_format(body,opt)
        if opt.capture:
            body=apply_captures(body,opt)
    if opt.color:
        body=colorize(body)
    return body

def main():
    opt,inputs=parse_args(sys.argv[1:])
    cases=read_cases(opt,inputs)
    print(build_regex(cases,opt))

if __name__=='__main__':
    main()
